149	
150	        String commandKey = key("tkc");
151	        String transferKey = key("tk");
152	        JsonNode result = postOk("/api/transfers",
153	                transferBody(commandKey, transferKey, source, target), "alice");
154	        assertEquals(transferKey, result.get("transferKey").asText());
155	        assertEquals(windowId, result.get("windowId").asLong());
156	        assertEquals(source, result.get("sourceAllocationKey").asText());
