    public List<ScheduleRow> listSchedulesByChannel(String channelId) {
        return jdbc.query(
                SCHEDULE_SELECT + " FROM rotation_schedule WHERE channel_id = ?"
                        + " ORDER BY start_nanos, id", SCHEDULE_MAPPER, channelId);
    }

