336	    // ------------------------------------------------------------------
337	    // 轮灌排班与用水核销
338	    // ------------------------------------------------------------------
339	
340	    private static final long NANOS_PER_MINUTE = 60L * NANOS_PER_SECOND;
341	    private static final long MIN_SLOT_NANOS = 30L * NANOS_PER_MINUTE;
342	    private static final long MAX_SLOT_NANOS = 720L * NANOS_PER_MINUTE;
343	    private static final int MAX_ACTIVE_SCHEDULES_PER_ALLOCATION = 3;
344	
345	    /**
346	     * 创建轮灌引水时段：渠道取自所属窗口；时段须为 30~720 分钟且完全落在窗口内；
347	     * 申请须 APPROVED、未取消且剩余未核销水量大于 0；同窗口最多持有 3 个生效时段；
348	     * 同渠道时间重叠（左闭右开，端点相接合法）返回 409 并给出全部冲突时段。
349	     */
350	    public ScheduleResponse createSchedule(String commandKey, String scheduleKey, String allocationKey,
351	                                           String startUtc, String endUtc, String actor) {
352	        requireKey("commandKey", commandKey);
353	        requireKey("scheduleKey", scheduleKey);
354	        requireKey("allocationKey", allocationKey);
355	        requireKey("X-Actor-Id", actor);
356	        long startNanos = parseInstant("startUtc", startUtc);
357	        long endNanos = parseInstant("endUtc", endUtc);
358	        long duration = endNanos - startNanos;
359	        if (duration < MIN_SLOT_NANOS || duration > MAX_SLOT_NANOS) {
360	            throw ApiException.badRequest("INVALID_ARGUMENT",
361	                    "引水时段时长必须在 30 至 720 分钟之间（含端点）");
362	        }
363	        String params = "SCHEDULE_CREATE|" + scheduleKey + "|" + allocationKey + "|" + startNanos + "|"
364	                + endNanos + "|" + actor;
365	        return runCommand("SCHEDULE_CREATE", commandKey, params, ScheduleResponse.class, () -> {
366	            if (repository.findScheduleByKey(scheduleKey) != null) {
367	                throw ApiException.conflict("SCHEDULE_KEY_REUSED", "scheduleKey 已被使用: " + scheduleKey);
368	            }
369	            AllocationRow allocation = repository.findAllocationByKey(allocationKey);
370	            if (allocation == null) {
371	                throw ApiException.notFound("ALLOCATION_NOT_FOUND", "配水申请不存在: " + allocationKey);
372	            }
373	            if (!allocation.requester().equals(actor)) {
374	                throw ApiException.conflict("NOT_OWNER", "只有申请人本人可以为该申请排班");
375	            }
376	            // 窗口行锁：与并发排班、转让、取消、核销按事务提交顺序串行裁决
377	            WindowRow window = lockWindowOf(allocation);
378	            // 锁内重读申请，得到最新状态、持有额度与累计核销
379	            allocation = repository.lockAllocationByKey(allocationKey);
380	            if (!STATUS_APPROVED.equals(allocation.status())) {
381	                throw ApiException.unprocessable("ALLOCATION_NOT_SCHEDULABLE",
382	                        "只有 APPROVED 且未取消的申请可以排班，当前状态: " + allocation.status(), null);
383	            }
384	            BigDecimal remaining = remainingOf(allocation);
385	            if (remaining.signum() <= 0) {
386	                throw ApiException.unprocessable("NO_REMAINING_WATER",
387	                        "申请剩余未核销水量为 0，不能再排班", null);
388	            }
389	            if (startNanos < window.startNanos() || endNanos > window.endNanos()) {
390	                throw ApiException.badRequest("SLOT_OUTSIDE_WINDOW",
391	                        "引水时段必须完全落在所属配水窗口 [" + toIso(window.startNanos()) + ", "
392	                                + toIso(window.endNanos()) + ") 内");
393	            }
394	            List<ScheduleRow> conflicts =
395	                    repository.findOverlappingActiveSchedules(window.channelId(), startNanos, endNanos);
396	            if (!conflicts.isEmpty()) {
397	                throw ApiException.conflict("SCHEDULE_OVERLAP",
398	                        "同一渠道在该时段已存在生效引水时段",
399	                        java.util.Map.of("conflicts", conflicts.stream().map(this::toScheduleResponse).toList()));
400	            }
401	            if (repository.countActiveSchedules(allocationKey, window.id())
402	                    >= MAX_ACTIVE_SCHEDULES_PER_ALLOCATION) {
403	                throw ApiException.unprocessable("TOO_MANY_SCHEDULES",
404	                        "单个申请在同一窗口内最多持有 " + MAX_ACTIVE_SCHEDULES_PER_ALLOCATION
405	                                + " 个生效时段", null);
406	            }
407	            long now = nowNanos();
408	            final long id;
409	            try {
410	                id = repository.insertSchedule(scheduleKey, window.channelId(), window.id(), allocationKey,
411	                        startNanos, endNanos, remaining, now);
